-- Household seed for BarangayLink. Populates the target database with
-- 35 households and 100 residents across Puroks 1-5, plus one
-- household_profiles row per household.
--
-- Prereq schema: database.sql, then database/migration_household_profiling.sql.
--   (poverty_thresholds id 1 = Surigao del Norte 2023, PHP 29,865.00 per capita/yr).
-- Run:  mysql -uroot barangay_system_test_environment < database/seed_households.sql
--
-- Contents: 35 households (ids 1-35, codes HH-0001..0035), 100 residents
-- (ids 1001-1100), one household_profiles row per household. Puroks 1-5.
-- Purok 1, 2, and 5 have 5 households each. Purok 3 and Purok 4 have 10
-- (households 26-30 were purok 6; households 31-35 were purok 7).
-- Temporary password: 'K4pitan-Seed#91'.
--
-- Seeded resident accounts share one temporary password. See the line
-- immediately below the "Contents" block for the plaintext. Rotate before
-- exposing the deployment.
--
-- Re-runnable: the DELETEs below remove household ids 1-35, the seeded
-- household_profiles rows, and the seeded resident accounts (ids 1001-1100).
--
-- Hand-computed assessment values (assessment_method_version = PSA-MPI-2025-v1).
-- The engine should reproduce these exactly; mismatches are integration bugs.
--
--   Weights (in 24ths; 4 dimensions x 6/24 each, equal split inside a dimension):
--     Education (3 each):  school_attendance        children_5_17_not_in_school > 0
--                          educational_attainment   members_19_plus_total > 0 AND has_19_plus_secondary_grad = 0
--     Health/Nutrition (2 each):
--                          hunger                   fies_hungry = 1 OR fies_whole_day_no_food = 1
--                          food_insecurity          SUM(fies_* 8 items) >= 4
--                          health_access            (medical_need_6mo = 1 AND medical_treatment_obtained = 0)
--                                                   OR distance_health_center_km > 5
--     Housing/Water/Sanitation (1 each):
--                          assets                   JSON_LENGTH(assets_json) < 2
--                          toilet                   toilet_facility IN ('None','Open pit') OR shared_toilet = 1
--                          water                    main_water_source IN ('Unprotected well','Unprotected spring',
--                                                   'River/stream','Rainwater','Peddler')
--                          tenure                   housing_tenure IN ('Informal settler','Rent-free without consent')
--                          materials                roof_material OR wall_material IN ('Light','Salvaged','Makeshift')
--                          electricity              has_electricity = 0
--     Employment (3 each): underemployment          unemployed_seeking_count > 0 OR employed_wanting_more_hours > 0
--                          working_children         working_children_not_in_school > 0
--   mpi_score  = deprived_24ths / 24, rounded to 4 dp.  mpi_status = 'poor' if score > 0.25,
--   'not_poor' otherwise, 'incomplete' if any indicator input is NULL (score NULL).
--
--   annual_household_income    = 12 * SUM(monthly_wages, monthly_business, monthly_remittances,
--                                         monthly_pension, monthly_govt_assistance, monthly_other)
--   annual_per_capita_income   = annual_household_income / household_size
--   income_poverty_status      = 'below' if per capita < 29,865.00 else 'at_or_above';
--                                'cannot_determine' when all six monthly_* fields are NULL.
--   profile_completeness       = ROUND(non-NULL questionnaire fields / 47 * 100)
--   assessment_complete        = 1 only when profile complete, MPI determined and income determined.
--
-- Distribution: 14 MPI poor / 19 not poor / 2 incomplete; 13 below threshold / 17 at or above /
-- 5 cannot_determine (the 5 in_progress households); 5 x 4Ps, 6 with a senior, 3 solo-parent,
-- 4 with a PWD member.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- Seeded rows are removed by id: household ids 1-35, resident ids 1001-1100.
-- Id-based deletion keeps the seed re-runnable regardless of how codes or
-- usernames are formatted. household_profiles must be deleted before
-- households for the FK to stay satisfied.
DELETE FROM `household_profiles` WHERE `household_id` BETWEEN 1 AND 35;
DELETE FROM `households`         WHERE `id`           BETWEEN 1 AND 35;
DELETE FROM `residents`          WHERE `id`           BETWEEN 1001 AND 1100;


